func (q *Queries) ListVolumesWithCounts(ctx context.Context, arg ListVolumesWithCountsParams) ([]ListVolumesWithCountsRow, error) {
	rows, err := q.db.Query(ctx, listVolumesWithCounts, arg.OrganizationID, arg.Limit, arg.Offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListVolumesWithCountsRow{}
	for rows.Next() {
		var i ListVolumesWithCountsRow
		if err := rows.Scan(
			&i.VolumeID,
			&i.DisplayName,
			&i.MountPoint,
			&i.ContainerNames,
			&i.IsActive,
			&i.TotalSizeBytes,
			&i.UsedSizeBytes,
			&i.FreeSizeBytes,
			&i.FilesystemType,
			&i.ContainerCount,
			&i.FirstSeenAt,
			&i.LastScanAt,
			&i.LastModifiedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.OrganizationID,
			&i.FileCount,
			&i.FolderCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

